mapper.select:
SELECT receivable_id, receivable_no, order_id, customer_id, settle_customer_id, settle_type, amount, received_amount, balance_amount, due_time, status, create_time FROM t_receivable
AND deleted_flag = #{queryForm.deletedFlag}
AND receivable_no LIKE CONCAT('%', #{queryForm.receivableNo}, '%')
AND customer_id = #{queryForm.customerId}
AND status = #{queryForm.status}
ORDER BY receivable_id DESC
